from flask import Flask, jsonify
from bitcoinlib.services.bitcoind import BitcoindClient

app = Flask(__name__)
bitcoind = BitcoindClient()

@app.route('/block/<block_hash>')
def get_block(block_hash):
    try:
        block = bitcoind.getblock(block_hash)
        return jsonify({
            "hash": block['hash'],
            "height": block['height'],
            "merkleroot": block['merkleroot'],
            "time": block['time'],
            "nonce": block['nonce'],
            "tx": block['tx']
        })
    except Exception as e:
        return jsonify({"error": str(e)}), 404

@app.route('/transaction/<txid>')
def get_transaction(txid):
    try:
        tx = bitcoind.getrawtransaction(txid, 1)
        return jsonify({
            "txid": tx['txid'],
            "blockhash": tx['blockhash'],
            "vin": [{"coinbase": v.get('coinbase', ''), "sequence": v['sequence']} for v in tx['vin']],
            "vout": [{
                "value": v['value'],
                "n": v['n'],
                "scriptPubKey": {
                    "asm": v['scriptPubKey']['asm'],
                    "hex": v['scriptPubKey']['hex'],
                    "type": v['scriptPubKey']['type']
                }
            } for v in tx['vout']]
        })
    except Exception as e:
        return jsonify({"error": str(e)}), 404

@app.route('/status')
def get_status():
    try:
        info = bitcoind.getnetworkinfo()
        return jsonify({"status": "online" if info['networkactive'] else "offline"})
    except Exception as e:
        return jsonify({"status": str(e)})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
EOF

