import io, re, compileall

p = "lib/ansible/module_utils/basic.py"
s = io.open(p, 'r', encoding='utf-8').read()

start = s.find("\ndef sanitize_mapping_keys(")
if start == -1:
    raise SystemExit("sanitize_mapping_keys start not found")
m = re.search(r"\ndef\s+\w", s[start+1:])
if not m:
    end = len(s)
else:
    end = start + 1 + m.start()

new_func = '''\
def sanitize_mapping_keys(value, no_log_strings=None, ignore_keys=None):
    """Sanitize only mapping keys predictably.

    - Non-dict-like values (strings, booleans, numbers, lists, sets, None, etc.) are returned unchanged.
    - For mapping keys that contain sensitive tokens, the key name is masked by replacing
      occurrences of those tokens with '********' (e.g., 'db-password' -> 'db-********').
    - For mapping keys that exactly match a sensitive token, the corresponding value is replaced
      with the sentinel 'VALUE_SPECIFIED_IN_NO_LOG_PARAMETER'.
    - An optional ignore list of exact keys will bypass masking/replacement for those keys.
    - Values are not modified except when a key exactly matches a sensitive token (sentinel value);
      however, nested mappings are processed recursively to sanitize their keys.
    """
    if not isinstance(value, Mapping):
        return value

    tokens = [to_native(s, errors='surrogate_or_strict') for s in (no_log_strings or ())]
    ignored = set(to_native(k, errors='surrogate_or_strict') for k in (ignore_keys or ()))

    def _process_map(mapping):
        new_mapping = type(mapping)() if isinstance(mapping, MutableMapping) else {}
        for k, v in mapping.items():
            new_k = k
            new_v = v

            if isinstance(k, (text_type, binary_type)):
                k_native = to_native(k, errors='surrogate_or_strict')

                if k_native in ignored:
                    # Keep key and value as-is (but still recurse into nested mappings)
                    if isinstance(v, Mapping):
                        new_v = _process_map(v)
                elif k_native in tokens:
                    # Exact key match: replace value with sentinel
                    new_v = 'VALUE_SPECIFIED_IN_NO_LOG_PARAMETER'
                else:
                    # Mask substrings in key
                    masked = k_native
                    for t in tokens:
                        if t:
                            masked = masked.replace(t, '*' * 8)
                    new_k = masked
                    if isinstance(v, Mapping):
                        new_v = _process_map(v)
            else:
                if isinstance(v, Mapping):
                    new_v = _process_map(v)

            new_mapping[new_k] = new_v
        return new_mapping

    return _process_map(value)
'''

new_s = s[:start] + "\n" + new_func + s[end:]
io.open(p, 'w', encoding='utf-8').write(new_s)

ok = compileall.compile_file(p, quiet=1)
print("COMPILE_OK" if ok else "COMPILE_FAIL")
